              gl.uniform2f(uTilt, curTx * 0.009 * sx, curTy * 0.009 * sy);
              gl.uniform2f(uMouse, pointerState.u, pointerState.v);
              gl.uniform1f(uTime, (now - startT) / 1000);
              gl.uniform1f(uPresence, presence);
              gl.drawArrays(gl.TRIANGLES, 0, 6);
